package com.myaaptha.domain.health;import com.myaaptha.domain.social.SocialPostRepository;import java.math.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class HealthService{private final HealthReportRepository reports;private final HealthMeasurementRepository measurements;private final SocialPostRepository posts;public HealthService(HealthReportRepository r,HealthMeasurementRepository m,SocialPostRepository p){reports=r;measurements=m;posts=p;}public record MeasurementInput(String metricName,BigDecimal value,String unit,BigDecimal referenceMin,BigDecimal referenceMax){}public record ReportInput(Long sourcePostId,String reportName,String laboratory,LocalDate collectedOn,String notes,List<MeasurementInput>measurements){}public record Measurement(Long id,String metricName,BigDecimal value,String unit,BigDecimal referenceMin,BigDecimal referenceMax,String rangeStatus){}public record Report(Long id,Long sourcePostId,String sourceMediaName,String sourceMediaUrl,String reportName,String laboratory,LocalDate collectedOn,String notes,List<Measurement>measurements){}public record TrendPoint(LocalDate date,BigDecimal value,BigDecimal referenceMin,BigDecimal referenceMax,Long reportId){}public record Trend(String metricName,String unit,List<TrendPoint>points){}public record Dashboard(List<Report>reports,List<Trend>trends,String disclaimer){}
 public Dashboard dashboard(Long user){List<Report>result=reports.findByUserIdOrderByCollectedOnDesc(user).stream().map(this::dto).toList();Map<String,List<Map.Entry<Report,Measurement>>>groups=new TreeMap<>();for(Report r:result)for(Measurement m:r.measurements())groups.computeIfAbsent(m.metricName().toLowerCase()+"|"+m.unit().toLowerCase(),x->new ArrayList<>()).add(Map.entry(r,m));List<Trend>trends=groups.values().stream().map(items->{var first=items.get(0).getValue();return new Trend(first.metricName(),first.unit(),items.stream().sorted(Comparator.comparing(x->x.getKey().collectedOn())).map(x->new TrendPoint(x.getKey().collectedOn(),x.getValue().value(),x.getValue().referenceMin(),x.getValue().referenceMax(),x.getKey().id())).toList());}).toList();return new Dashboard(result,trends,"Charts organize values you enter and compare them only with the reference range printed by your laboratory. They do not diagnose illness or replace a clinician.");}
 public Report add(Long user,ReportInput input){if(input==null||input.reportName()==null||input.reportName().isBlank()||input.collectedOn()==null)bad("Report name and collection date are required");if(input.sourcePostId()!=null)posts.findById(input.sourcePostId()).filter(p->p.getAuthorUserId().equals(user)&&"PRIVATE".equals(p.getAudience())&&p.getMediaKey()!=null).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose one of your private diary documents"));HealthReportEntity r=new HealthReportEntity();r.setUserId(user);r.setSourcePostId(input.sourcePostId());r.setReportName(trim(input.reportName(),200));r.setLaboratory(trim(input.laboratory(),200));r.setCollectedOn(input.collectedOn());r.setNotes(trim(input.notes(),1000));r=reports.save(r);for(MeasurementInput value:input.measurements()==null?List.<MeasurementInput>of():input.measurements())saveMeasurement(r.getId(),value);return dto(r);}
 public void delete(Long user,Long id){HealthReportEntity r=reports.findById(id).filter(x->x.getUserId().equals(user)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));measurements.deleteByReportId(id);reports.delete(r);}
 private void saveMeasurement(Long report,MeasurementInput in){if(in.metricName()==null||in.metricName().isBlank()||in.value()==null||in.unit()==null||in.unit().isBlank())bad("Each measurement needs a name, value and unit");if(in.referenceMin()!=null&&in.referenceMax()!=null&&in.referenceMin().compareTo(in.referenceMax())>0)bad("Reference minimum cannot exceed maximum");HealthMeasurementEntity e=new HealthMeasurementEntity();e.setReportId(report);e.setMetricName(trim(in.metricName(),120));e.setValue(in.value());e.setUnit(trim(in.unit(),40));e.setReferenceMin(in.referenceMin());e.setReferenceMax(in.referenceMax());measurements.save(e);}
 private Report dto(HealthReportEntity r){var post=r.getSourcePostId()==null?null:posts.findById(r.getSourcePostId()).orElse(null);return new Report(r.getId(),r.getSourcePostId(),post==null?null:post.getMediaName(),post==null?null:"/api/social/posts/"+post.getId()+"/media",r.getReportName(),r.getLaboratory(),r.getCollectedOn(),r.getNotes(),measurements.findByReportId(r.getId()).stream().map(this::dto).toList());}private Measurement dto(HealthMeasurementEntity m){String status=m.getReferenceMin()!=null&&m.getValue().compareTo(m.getReferenceMin())<0?"BELOW":m.getReferenceMax()!=null&&m.getValue().compareTo(m.getReferenceMax())>0?"ABOVE":"IN_RANGE";return new Measurement(m.getId(),m.getMetricName(),m.getValue(),m.getUnit(),m.getReferenceMin(),m.getReferenceMax(),status);}private static String trim(String x,int n){if(x==null)return null;String v=x.trim();return v.substring(0,Math.min(n,v.length()));}private static void bad(String x){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,x);}}
